        return True

    if trap_bad_request:
        return isinstance(e, BadRequest)

    return False

def untag(self, value: dict[str, t.Any]) -> t.Any:
    if len(value) != 1:
        return value

    key = next(iter(value))

    if key not in self.tags:
        return value

    return self.tags[key].to_python(value[key])

